//! EvoBuddy's own icon set.
//!
//! The PNGs under `assets/icons/` are generated by `assets/gen_icons.py` from
//! simple geometric primitives; they are not copied from the product or an
//! icon theme. Keeping them as embedded bytes avoids a runtime asset path, an
//! icon-theme dependency and librsvg differences between platforms.

use gtk::prelude::*;

fn bytes(name: &str) -> Option<&'static [u8]> {
    Some(match name {
        "plus" => include_bytes!("../assets/icons/plus.png"),
        "assistant" => include_bytes!("../assets/icons/assistant.png"),
        "grid" => include_bytes!("../assets/icons/grid.png"),
        "calendar" => include_bytes!("../assets/icons/calendar.png"),
        "library" => include_bytes!("../assets/icons/library.png"),
        "search" => include_bytes!("../assets/icons/search.png"),
        "share" => include_bytes!("../assets/icons/share.png"),
        "copy" => include_bytes!("../assets/icons/copy.png"),
        "expand" => include_bytes!("../assets/icons/expand.png"),
        "collapse" => include_bytes!("../assets/icons/collapse.png"),
        "close" => include_bytes!("../assets/icons/close.png"),
        "code" => include_bytes!("../assets/icons/code.png"),
        "send" => include_bytes!("../assets/icons/send.png"),
        "stop" => include_bytes!("../assets/icons/stop.png"),
        "menu" => include_bytes!("../assets/icons/menu.png"),
        "filter" => include_bytes!("../assets/icons/filter.png"),
        "user" => include_bytes!("../assets/icons/user.png"),
        "chevron-down" => include_bytes!("../assets/icons/chevron-down.png"),
        "chevron-right" => include_bytes!("../assets/icons/chevron-right.png"),
        "check" => include_bytes!("../assets/icons/check.png"),
        "ring" => include_bytes!("../assets/icons/ring.png"),
        "logo" => include_bytes!("../assets/icons/logo.png"),
        "agent" => include_bytes!("../assets/icons/agent.png"),
        "thumb-up" => include_bytes!("../assets/icons/thumb-up.png"),
        "thumb-down" => include_bytes!("../assets/icons/thumb-down.png"),
        "mascot" => include_bytes!("../assets/mascot.png"),
        _ => return None,
    })
}

/// Load an icon by name. Unknown names return `None` so callers can fall back
/// to a text glyph during the transition.
pub fn image(name: &str, size: i32) -> Option<gtk::Image> {
    let loader = gtk::gdk_pixbuf::PixbufLoader::new();
    loader.write(bytes(name)?).ok()?;
    loader.close().ok()?;
    let pixbuf = loader.pixbuf()?;
    // `GtkImage::set_pixel_size` is ignored for a pixbuf-backed image in GTK3;
    // scale the source explicitly so a 48px asset does not render at 48px.
    let scaled = pixbuf.scale_simple(
        size,
        size,
        gtk::gdk_pixbuf::InterpType::Bilinear,
    )?;
    let image = gtk::Image::from_pixbuf(Some(&scaled));
    Some(image)
}

/// The existing call sites pass the product's text glyphs. Map the ones we
/// draw; anything else keeps the old label so an unknown glyph is visible
/// rather than silently disappearing.
pub fn request(value: &str, class_name: &str) -> gtk::Widget {
    let name = match value {
        "+" => "plus",
        "◆" => "assistant",
        "▦" => "grid",
        "◻" => "calendar",
        "▤" => "library",
        "◉" => "search",
        "⤴" => "share",
        "⧉" => "copy",
        "⤢" => "expand",
        "◧" | "▥" => "collapse",
        "×" => "close",
        "✎" => "code",
        "↑" => "send",
        "■" => "stop",
        "≡" => "menu",
        "▣" => "user",
        "⌄" => "chevron-down",
        "›" | "▶" | "▸" => "chevron-right",
        "◌" => "ring",
        _ => "",
    };
    if let Some(image) = image(name, 20) {
        image.upcast()
    } else {
        let label = gtk::Label::new(Some(value));
        crate::widgets::class(&label, class_name);
        label.upcast()
    }
}

/// Fixed semantic icon for places that previously used a special label.
pub fn named(name: &str, size: i32, class_name: &str) -> gtk::Widget {
    if let Some(image) = image(name, size) {
        image.upcast()
    } else {
        let label = gtk::Label::new(None);
        crate::widgets::class(&label, class_name);
        label.upcast()
    }
}
